const sourceIcon = (source) => `<span class="source-icon ${esc(source)}">${icon(SOURCES[source]?.icon || 'mail')}</span>`;
const button = (label, act, symbol, type='') => `<button class="btn ${type}" data-act="${esc(act)}">${symbol?icon(symbol):''}${esc(label)}</button>`;
function fmt(value, options={hour:'2-digit',minute:'2-digit'}) { return new Intl.DateTimeFormat('zh-CN',{timeZone:state.timezone,...options}).format(new Date(value)); }
function dateKey(value=new Date()) { return new Intl.DateTimeFormat('en-CA',{timeZone:state.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value)); }
function shiftDate(date, offset) { const d=new Date(date+'T12:00:00Z'); d.setUTCDate(d.getUTCDate()+offset); return d.toISOString().slice(0,10); }
function zoned(date, clock) {
  const target = new Date(date+'T'+clock+':00Z').getTime();
  let result = target;
  for(let i=0;i<3;i++){
    const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:state.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(result).map(p=>[p.type,p.value]));
    const represented=Date.parse(`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}Z`);
    result += target-represented;
  }
  return new Date(result).toISOString();
}
function elapsed(value) { const minutes=Math.max(0,Math.floor((Date.now()-Date.parse(value))/60000));return minutes<60?`${minutes} 分钟前`:minutes<1440?`${Math.floor(minutes/60)} 小时前`:fmt(value,{month:'2-digit',day:'2-digit'}); }
function toast(message){ $('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3600); }
async function api(path, method='GET', body) {
  const response=await fetch(path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-Relay-Request':'1','X-CSRF-Token':state.csrf},...(body===undefined?{}:{body:JSON.stringify(body)})});
  if(!response.ok){
    let data;try{data=await response.json();}catch{data={};}
    if(response.status===401){state.authenticated=false;state.csrf='';state.demo=true;state.data=demoData();state.reminders=[];state.agentSuggestion=null;state.pendingPlan=null;closeModal();render();}
    throw new Error(typeof data.detail==='string'?data.detail:'输入格式不正确，请检查各字段');
  }
  return response.json();
}
